head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.gJobTitle = js_jobtitl; // 팀장  : 09,  부서장: 40,  팀원: 03
scwin.gSelectedLdMktTpCd; // 선택된 법인의 시장코드

scwin.gIsurCd;
scwin.gMktTp;
scwin.vScrenID = "ULDSTF30601.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_Init = function() {
    $c.stf.setObjectValue(rdo_MARKET_FLAG, scwin.gLdMktTp);
    if (scwin.gDepCd.substr(0, 2) != '32') {
        //코스닥은 공시팀 외에는 전체를 default로 한다. (YSH, 2008/11/05) 
        $c.stf.setObjectValue(cmb_DEP_CD, js_dep_cd);
        $c.stf.setObjectValue(cmb_EMP_NO, js_emp_no);
    }
    var ISUR_CD = $c.stf.getQuery(frame.srcUrl, "ISUR_CD"); // 다른 페이지(기업정보조회)에서 넘어오는 경우 처리.
    //alert(frame.srcUrl);
    $c.stf.setObjectValue(txb_ISUR_CD, ISUR_CD);
    chb_Grp_All.setValue(1); //처음화면 로딩시 체크박스 전체를 TRUE 로 놓는다.

    //코스닥은 공시담당보조자 없다. 유가일때만 보이게 한다.(2010.12.15 P.H.J)
    if (scwin.gLdMktTp == '2') {
        $c.stf.showObj(panel_8, false);
        panel_7.style.top = "976";
    }

    //유가일때는 소속부 항목을 노출시키지 않는다.(2012.03.23 L.D.J)
    if (scwin.gLdMktTp == '1') {
        // 1. 그리드에서 항목 숨기기 및 회사명 항목 width 증가
        $c.cm.setColumnProp(grd_List, "SECT_TP_CD", "Show", false);
        $c.cm.setColumnProp(grd_List, 'COM_ABBRV', 'Width', '220'); //Original Width : 110

        // 2. 회사개요에서 항목 숨기기 및 주요제품 항목 width 증가
        $c.stf.showObj(label_115, false);
        $c.stf.showObj(txb_SECT_TP_CD, false);
        //txb_Corp_MAJ_PROD_NM.style.width= "525px"; //Original Width : 200 

        // 3. 엑셀다운로드 그리드에서 항목 제외
        $c.cm.setColumnProp(grd_List2, "SECT_TP_CD", "Show", false);
        $c.cm.setColumnProp(grd_List2, "PHARMA_BIO_COM_YN", "Show", false);
    }
};
scwin.fn_GetProvider = function() {
    var url = frame.srcUrl;
    var arr = url.split("?");

    //alert(url +"     =      "+ arr);
    return (arr.length >= 1 ? $c.frame.path("../" + arr[1]) : undefined);
};
scwin.fn_GetParentValue = function() {
    var pvd = scwin.fn_GetProvider();
    if (pvd != null) {
        scwin.gMktTp = pvd.scwin.gMktTp;
        scwin.gIsurCd = pvd.scwin.gIsurCd;
        if ($c.ut.trim(scwin.gIsurCd).length == 5) {
            scwin.fn_InitSearch();
        }
    }
};
scwin.fn_setCodes = function() {
    dts_EMP_NO.DataID = "/CodeAction.do?method=getEmpNoDepCode&inputMessageId=CODE_EMPDEP_IN&For=R&DEP_CD=" + scwin.gDepCd;
    dts_EMP_NO.Reset();
    dts_DEP_CD.DataID = "/CodeAction.do?method=getDepUpCode&inputMessageId=CODE_EMPDEP_IN&For=R&DEP_CD=" + scwin.gDepCd;
    dts_DEP_CD.Reset();
    /*
    	dts_ATTR_TP_CD.DataID = "/CodeAction.do?method=listCodeValueName&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT&FOR=R&CD_ENG_NM=COM_ATTR_TP_CD";
    	dts_ATTR_TP_CD.Reset();
    	*/

    dts_Delete.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=CORP_DISCLS_CHRG_INOUT";
    dts_Delete.Reset();
};
scwin.fn_Search = function() {
    $c.cm.ShowWin(grd_List);
    var vMARKET_FLAG = $c.stf.getObjectValue(rdo_MARKET_FLAG);
    var vDEP_CD = $c.stf.getObjectValue(cmb_DEP_CD);
    var vISUR_CD = $c.stf.getObjectValue(txb_ISUR_CD);
    var vEMP_NO = $c.stf.getObjectValue(cmb_EMP_NO);
    //var vATTR_TP_CD = getObjectValue(cmb_ATTR_TP_CD); //회사속성
    var vLIST_STATUS = 'Y';
    if (vMARKET_FLAG == "" && vDEP_CD == "" && vISUR_CD == "" && vEMP_NO == "") {
        $c.win.alert("[검색조건]을 하나이상 선택하세요.");
        return;
    }
    var secuGrpId = "";
    if ($c.stf.getObjectValue(chb_Grp_St) == 'Y') secuGrpId += 'ST,';
    if ($c.stf.getObjectValue(chb_Grp_Mf) == 'Y') secuGrpId += 'MF,';
    if ($c.stf.getObjectValue(chb_Grp_Rt) == 'Y') secuGrpId += 'RT,';
    if ($c.stf.getObjectValue(chb_Grp_Sc) == 'Y') secuGrpId += 'SC,';
    if ($c.stf.getObjectValue(chb_Grp_Fs) == 'Y') secuGrpId += 'FS,';
    if ($c.stf.getObjectValue(chb_Grp_Dr) == 'Y') secuGrpId += 'DR,';
    if ($c.stf.getObjectValue(chb_Grp_If) == 'Y') secuGrpId += 'IF,';
    if ($c.stf.getObjectValue(chb_Grp_All) == ' Y') secuGrpId = '';
    var url = "/ListedCompany.do?method=listChargeIssue";
    url += "&MARKET_FLAG=" + vMARKET_FLAG;
    url += "&DEP_CD=" + vDEP_CD;
    url += "&ISUR_CD=" + vISUR_CD;
    url += "&EMP_NO=" + vEMP_NO;
    //url += "&ATTR_TP_CD=" + vATTR_TP_CD; //회사속성
    url += "&LIST_STATUS=" + vLIST_STATUS;
    url += "&SECU_GRP_ID=" + secuGrpId;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_Grid.DataID = encodeURI(url);
    dts_Grid.Reset();
    if (dts_Grid.getTotalRow() > 0) {
        scwin.fn_readChargeIssue(grd_List, 1, "ISUR_CD");
    } else {
        dts_Corp_Info.removeAll();
        dts_Krx_Emp_Info.removeAll();
        dts_Charge1_Info.removeAll();
        dts_Charge2_Info.removeAll();
        dts_Charge3_Info.removeAll();
        dts_Charge4_Info.removeAll();
    }
};



// 다른창에서 담당종목 조회를 클릭할때
scwin.fn_InitSearch = function() {
    scwin.fn_getChargeIssue(scwin.gIsurCd, scwin.gMktTp);
};
scwin.fn_readChargeIssue = function(GridID, row, colid) {
    if (row < 1) return;
    var objDataID = document.all(GridID.DataID); // 가져오는 방식이 좀 특이하다..

    var vISUR_CD = objDataID.getCellData(row, "ISUR_CD");
    scwin.gIsurCd = vISUR_CD; //회사정보 팝업때문에
    var vMKT_TP_CD = objDataID.getCellData(row, "SPOT_ISU_TRD_MKT_TP_CD");
    scwin.gSelectedLdMktTpCd = vMKT_TP_CD; //20180802

    scwin.fn_getChargeIssue(vISUR_CD, vMKT_TP_CD);
};
scwin.fn_getChargeIssue = function(vISUR_CD, vMKT_TP_CD) {
    scwin.fn_HideCorpEmpLabels(vMKT_TP_CD); //코스닥 숨기기.

    //var url = "/ListedCompany.do?methodChargeIssue&Flag=1&ISUR_CD=" + vISUR_CD;
    var url = "/ListedCompany.do?method=readChargeIssue&Flag=1&ISUR_CD=" + vISUR_CD + "&BOND_YN=N";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

    // 회사정보
    dts_Corp_Info.DataID = encodeURI(url);
    dts_Corp_Info.Reset();


    //상공부 담당자 정보
    url = "/ListedCompany.do?method=readChargeIssue&Flag=2&ISUR_CD=" + vISUR_CD;
    dts_Krx_Emp_Info.DataID = encodeURI(url);
    dts_Krx_Emp_Info.Reset();

    // 공시책임자(유, 코)
    url = "/ListedCompany.do?method=readChargeIssue&Flag=3&ISUR_CD=" + vISUR_CD + "&MKT_TP_CD=" + vMKT_TP_CD;
    dts_Charge1_Info.DataID = encodeURI(url);
    dts_Charge1_Info.Reset();

    // 공시담당자1, 공시담당자(유, 코)
    url = "/ListedCompany.do?method=readChargeIssue&Flag=4&ISUR_CD=" + vISUR_CD + "&MKT_TP_CD=" + vMKT_TP_CD;
    dts_Charge2_Info.DataID = encodeURI(url);
    dts_Charge2_Info.Reset();

    // 공시담당자2, 공시실무자(유, 코)
    url = "/ListedCompany.do?method=readChargeIssue&Flag=5&ISUR_CD=" + vISUR_CD + "&MKT_TP_CD=" + vMKT_TP_CD;
    dts_Charge3_Info.DataID = encodeURI(url);
    dts_Charge3_Info.Reset();

    // 공시대리인(유) 
    url = "/ListedCompany.do?method=readChargeIssue&Flag=6&ISUR_CD=" + vISUR_CD + "&MKT_TP_CD=" + vMKT_TP_CD;
    dts_Charge4_Info.DataID = encodeURI(url);
    dts_Charge4_Info.Reset();

    //if (vMKT_TP_CD == '1') {

    //공시담당보조자(유)
    url = "/ListedCompany.do?method=readChargeIssue&Flag=10&ISUR_CD=" + vISUR_CD + "&MKT_TP_CD=" + vMKT_TP_CD;
    dts_Charge5_Info.DataID = encodeURI(url);
    dts_Charge5_Info.Reset();
    //}

    //삭제 버튼 노출여부 20180802
    if ($c.stf.getObjectValue(txb_Chrg3_Chrg_Tp_Cd) != "" && $c.stf.getObjectValue(txb_Chrg3_Chrg_Tp_Cd).length > 0) $c.stf.showObj(btn_Delete_3, true);

    else $c.stf.showObj(btn_Delete_3, false);

    //유가 당당자(부) 삭제버튼 잠금
    //if (vMKT_TP_CD == '1')	showObj(btn_Delete_3, false);

    if ($c.stf.getObjectValue(txb_Krx_Emp_DEP_CD) != scwin.gDepCd && scwin.gDepCd != "ZSYS" || $c.stf.getObjectValue(txb_LIST_STAT_CD) != "Y") {
        $c.stf.showObj(btn_Delete_3, false);
    }
    if (scwin.gEmpNo.indexOf("sysm") > -1) $c.stf.showObj(btn_Delete_4, true);

    //alert("gJobTitle : " + gJobTitle + " , " + "gDepCd : " + gDepCd+ " , " + "gEmpNo : " + gEmpNo);

    var vStr = $c.stf.getObjectValue(txb_Corp_CAP);
    if (vStr != "") {
        vStr2 = $c.stf.FormatNumberEx(vStr);
        $c.stf.setObjectValue(txb_Corp_CAP, vStr2);
    }
};
scwin.fn_HideCorpEmpLabels = function(flag) {
    var vStockLabels = new Array(lbl_CorpEmp2, lbl_CorpEmp3);
    var vKosdaqLabels = new Array(lbl_CorpEmp2_1, lbl_CorpEmp3_1);
    // 유가는 초기값을 가지고 있으므로 위치 이동은 없다.
    if (flag == "1") {
        // 유가. => 코스닥 숨기고 유가 위치이동 및 보이기.

        for (var i = 0; i < vKosdaqLabels.length; i++) {
            $c.stf.showObj(vKosdaqLabels[i], false);
            $c.stf.showObj(vStockLabels[i], true);
        }
    } else if (flag == "2" || flag == "6") {
        // 코스닥.=>유가를 숨기고 코스닥 위치이동 및 보이기
        for (var i = 0; i < vStockLabels.length; i++) {
            $c.stf.SetWindowPos(vKosdaqLabels[i], vStockLabels[i].style.top, vStockLabels[i].style.left, vStockLabels[i].style.getStyle("width"), vStockLabels[i].style.getStyle("height"));
            $c.stf.showObj(eval(vStockLabels[i]), false);
            $c.stf.showObj(vKosdaqLabels[i], true);
        }
    }
};




//유가와 코스닥이 보여주는 내용이 다름 20140411 sim
scwin.fn_HideDebugCtrls = function() {
    $c.stf.showObj(panel_mkt, false);
    $c.stf.showObj(panel_debug, false);
    if (js_market == "1") {
        $c.stf.showObj(btn_Resume, true);
        $c.stf.setObjectValue(lb_Chrg1_EDU_CRS_NM, "책임자과정이수여부");
        $c.stf.setObjectValue(lb_Chrg1_EDU_COMPLT_DD, "책임자과정이수시기");
        $c.stf.setObjectValue(lb_Chrg2_EDU_CRS_NM, "주식전문연수이수여부");
        $c.stf.setObjectValue(lb_Chrg2_EDU_COMPLT_DD, "주식전문연수이수시기");
        $c.stf.setObjectValue(lb_Chrg3_EDU_CRS_NM, "주식전문연수이수여부");
        $c.stf.setObjectValue(lb_Chrg3_EDU_COMPLT_DD, "주식전문연수이수시기");
        $c.stf.setObjectValue(lb_Chrg4_EDU_CRS_NM, "주식전문연수이수여부");
        $c.stf.setObjectValue(lb_Chrg4_EDU_COMPLT_DD, "주식전문연수이수시기");
        $c.stf.setObjectValue(lb_Chrg5_EDU_CRS_NM, "주식전문연수이수여부");
        $c.stf.setObjectValue(lb_Chrg5_EDU_COMPLT_DD, "주식전문연수이수시기");
    } else {
        $c.stf.showObj(btn_Resume, false);
    }
};
scwin.fn_changeFormat = function() {
    var ar = new Array(txb_Corp_RGHT_LIST_DD, txb_Chrg1_EDU_COMPLT_DD, txb_Chrg1_CHRG_DESIGN_DD, txb_Chrg1_WORK_TM, txb_Chrg2_WORK_TM, txb_Chrg3_WORK_TM, txb_Chrg2_EDU_COMPLT_DD, txb_Chrg2_CHRG_DESIGN_DD, txb_Chrg3_EDU_COMPLT_DD, txb_Chrg3_CHRG_DESIGN_DD);
    for (var i = 0; i < ar.length; i++) {
        var bfVal = $c.stf.getObjectValue(ar[i]);
        if (bfVal != "") {
            var afVal = $c.stf.FormatDateEx(bfVal);
            $c.stf.setObjectValue(ar[i], afVal);
        }
    }
};
scwin.fn_OpenResume = function() {
    $c.frame.path("../../").GWinOpen("ULDSTF30612", "/issueinfo/ULDSTF30612.gfm", "이력조회", 20, 20, 1270, 780, "");
};
scwin.FormatDateEx = function(str) {
    if (str == "") return "";
    return str.substring(0, 4) + "-" + str.substring(4, 6) + "-" + str.substring(6, 8);
};
scwin.fn_allCheck = function() {
    var checkArray = [chb_Grp_St, chb_Grp_Mf, chb_Grp_Sc, chb_Grp_Rt, chb_Grp_Dr, chb_Grp_Fs, chb_Grp_If];
    if (chb_Grp_All.checked == true) {
        for (var i = 0; i < checkArray.length; i++) {
            checkArray[i].setValue(0);
        }
    }
};
scwin.fn_Delete = function(gbn) {
    var txb_Chrg_Chrg_Tp_Cd_value;
    var txb_Chrg_Discls_Bz_Chrg_Assgn_Dd_value;
    var txb_Chrg_CHRG_NM_value;
    var txb_Chrg_JOBTITL_NM_value;
    var del_msg;
    if (gbn == "3") {
        txb_Chrg_Chrg_Tp_Cd_value = $c.stf.getObjectValue(txb_Chrg3_Chrg_Tp_Cd);
        txb_Chrg_Discls_Bz_Chrg_Assgn_Dd_value = $c.stf.getObjectValue(txb_Chrg3_Discls_Bz_Chrg_Assgn_Dd);
        txb_Chrg_CHRG_NM_value = $c.stf.getObjectValue(txb_Chrg3_CHRG_NM);
        txb_Chrg_JOBTITL_NM_value = $c.stf.getObjectValue(txb_Chrg3_JOBTITL_NM);
    }
    if (scwin.gSelectedLdMktTpCd == "1") {
        del_msg = "공시담당자(부) ";
    } else {
        del_msg = "공시 실무자 ";
    }
    del_msg += txb_Chrg_CHRG_NM_value + " " + txb_Chrg_JOBTITL_NM_value + " 님을";
    var res = window.confirm(del_msg + " 삭제하시겠습니까?");
    if (res) {
        dts_Delete.removeAll();
        dts_Delete.insertRow();
        dts_Delete.setCellData(1, "ISUR_CD", scwin.gIsurCd);
        dts_Delete.setCellData(1, "CHRG_TP_CD", txb_Chrg_Chrg_Tp_Cd_value);
        dts_Delete.setCellData(1, "DISCLS_BZ_CHRG_ASSGN_DD", txb_Chrg_Discls_Bz_Chrg_Assgn_Dd_value);
        dts_Delete.setCellData(1, "TRANSTR_EMP_NO", scwin.gEmpNo);
        trs_Save.Action = "/ListedCompany.do?method=delCorpDisclsChrg&inputMessageId=CORP_DISCLS_CHRG_INOUT&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInput=dts_Delete)";
        trs_Save.Post();
    }
};
scwin.btn_CorpInfo_onclick = function() {
    if (txb_Corp_COM_NM.getValue() == "") {
        $c.win.alert("회사를 선택하여 주십시오");
    } else {
        $c.stf.fn_PopupCorpInfo();
    }
};
scwin.btn_Search_onclick = function() {
    scwin.fn_Search();
};
scwin.grd_List_OnClick = function(row, colid) {
    scwin.fn_readChargeIssue(grd_List, row, colid);
};
scwin.dts_Grid_OnLoadError = function() {
    $c.stf.alert_error(dts_Grid);
};
scwin.rdo_MARKET_FLAG_OnSelChange = function() {
    scwin.fn_HideCorpEmpLabels($c.stf.getObjectValue(rdo_MARKET_FLAG));
};
scwin.cmb_DEP_CD_OnSelChange = function() {
    dts_EMP_NO.sort("DEP_CD", 0);
    //dts_EMP_NO.sort(); // W-Craft 주석처리 
    dts_EMP_NO.UseFilter = true;
    dts_EMP_NO.Filter();
};
scwin.dts_EMP_NO_OnFilter = function(row) {
    //  부서코드에  해당하는 사원을 가져온다.
    var vVal = $c.stf.getObjectValue(cmb_DEP_CD);
    if (vVal == "") {
        // 전체일 경우
        return true;
    } else {
        var vVal2 = dts_EMP_NO.getCellData(row, "dep_cd"); // 전체.
        if (vVal2 == "") return true; // 전체.
        return (vVal == vVal2) ? true : false;
    }
};
scwin.dts_Grid_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, grd_List);
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    scwin.fn_readChargeIssue(grd_List, 1, "ISUR_CD");
};
scwin.btn_ISUR_CD_onclick = function() {
    $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM);
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else {
        return true;
    }
};
scwin.txb_ISUR_CD_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_ISUR_CD.getValue() == "") {
        txb_COM_NM.setValue("");
    }
};
scwin.txb_ISUR_CD_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_ISUR_CD_onkeyup = function() {
    if (txb_ISUR_CD.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
